async function managerPage(){
 await loadLeagues();
 const own=await getDocs(query(collection(db,"teams"),where("managerUid","==",state.user.uid),limit(50))).catch(()=>getDocs(query(collection(db,"teams"),where("createdBy","==",state.user.uid),limit(50))));
 const teams=own.docs.map(d=>({id:d.id,...d.data()}));
 const reqSnap=await getDocs(query(collection(db,"transferRequests"),where("managerUid","==",state.user.uid),limit(100))).catch(()=>({docs:[]}));
 const pendingRequests=reqSnap.docs.filter(d=>d.data().status==="pending");
 const requestRows=pendingRequests.map(d=>{const x=d.data();return `<div class="history-row"><div><b>${esc(x.playerName||"Jugador")}</b><small>${esc(x.teamName||"Equipo")} · ${esc(x.position||"Posición por definir")} · ${esc(x.playerEmail||"")}</small></div><div class="inline-actions"><button class="btn-secondary" data-transfer-approve="${d.id}">Aceptar</button><button class="btn-quiet" data-transfer-reject="${d.id}">Rechazar</button></div></div>`}).join("");
 return `<section class="manager-hero"><div><div class="eyebrow">CENTRO DE GESTIÓN DEPORTIVA</div><h2>Tu equipo, tu proyecto.</h2><p>Administra tus plantillas, revisa solicitudes y organiza el trabajo deportivo de tu club.</p></div><div class="manager-ball">⚽</div></section>
 <section class="stats"><article class="stat"><small>Equipos que administras</small><strong>${teams.length}</strong><span>Plantillas bajo tu gestión</span></article><article class="stat"><small>Solicitudes pendientes</small><strong>${pendingRequests.length}</strong><span>Jugadores interesados</span></article></section>
 <section class="panel form-panel"><div class="panel-head"><div><div class="eyebrow green">REGISTRAR EQUIPO</div><h3>Solicitar alta de equipo</h3></div></div><p class="muted">Tu equipo será revisado por la administración antes de quedar habilitado en las competiciones.</p><form id="team-request-form" class="data-form"><label>Nombre del equipo<input name="teamName" required maxlength="100"></label><label>Municipio<input name="city" maxlength="80"></label><label>Rama<select name="branch"><option>Varonil</option><option>Femenil</option><option>Juvenil</option></select></label><label>Categoría<input name="category" placeholder="Libre, Sub-17..."></label><label>Temporada<input name="season" placeholder="2026-2027"></label><div class="wide"><button class="btn-primary">Enviar solicitud →</button></div></form></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">MIS EQUIPOS</div><h3>Plantillas administradas</h3></div></div>${teams.length?teams.map(t=>`<article class="manager-team"><div><span class="league-tag">${esc(t.branch||"Fútbol 11")} · ${esc(t.category||"Libre")}</span><h3>${esc(t.name)}</h3><p>${esc(t.city||"")} · ${esc(t.season||"Temporada por definir")}</p></div><button class="btn-secondary" data-manage-team="${t.id}">Administrar plantilla →</button></article>`).join(""):'<div class="empty-state">Todavía no administras equipos. Crea tu primer equipo para comenzar.</div>'}</section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">MERCADO DE JUGADORES</div><h3>Solicitudes de incorporación</h3></div></div>${requestRows||'<div class="empty-state">No tienes solicitudes pendientes de jugadores.</div>'}</section><div id="manager-team-detail"></div>`;
}
async function playerCareerPage(){
 const p=state.profile;
 const req=await getDocs(query(collection(db,"transferRequests"),where("playerUid","==",state.user.uid),limit(50))).catch(()=>({docs:[]}));
 const teams=await getDocs(query(collection(db,"teams"),where("status","==","active"),limit(80)));
 const rows=teams.docs.map(d=>{const t=d.data();return `<article class="league-card"><span class="league-tag">${esc(t.branch||"Fútbol 11")} · ${esc(t.category||"Libre")}</span><h3>${esc(t.name)}</h3><p>${esc(t.city||"")} · ${esc(t.leagueName||"Sin competición")}</p><button class="btn-secondary" data-request-team="${d.id}">Solicitar incorporación →</button></article>`}).join("");
 return `<section class="manager-hero player-hero"><div><div class="eyebrow">MI CARRERA DEPORTIVA</div><h2>${esc(p.displayName||state.user.displayName||"Jugador")}</h2><p>Tu trayectoria, tus estadísticas y las oportunidades para seguir creciendo.</p></div><div class="manager-ball">♟</div></section>
 <section class="stats"><article class="stat"><small>Equipo actual</small><strong class="career-stat">${esc(p.teamName||"Libre")}</strong><span>${esc(p.position||"Posición por definir")}</span></article><article class="stat"><small>Valoración</small><strong>${Number(p.rating||0)||"—"}</strong><span>Se mostrará cuando exista una evaluación validada</span></article><article class="stat"><small>Partidos</small><strong>${Number(p.matchesPlayed||0)}</strong><span>Registros oficiales</span></article><article class="stat"><small>Goles / asistencias</small><strong>${Number(p.goals||0)} / ${Number(p.assists||0)}</strong><span>Estadísticas registradas</span></article></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">OPORTUNIDADES</div><h3>Buscar club</h3></div></div><p class="muted">Explora equipos activos y envía una solicitud de incorporación. El club deberá revisar y responder.</p><div class="league-grid">${rows||'<div class="empty-state">Todavía no hay equipos disponibles.</div>'}</div></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">SEGUIMIENTO</div><h3>Mis solicitudes</h3></div></div>${req.docs.length?req.docs.map(d=>{const x=d.data();return `<div class="history-row"><div><b>${esc(x.teamName||"Equipo")}</b><small>${esc(x.position||"")} · ${x.createdAt?.toDate?x.createdAt.toDate().toLocaleDateString("es-MX"):"Solicitud enviada"}</small></div><span class="status-pill ${x.status==="accepted"?"good":x.status==="rejected"?"bad":""}">${x.status==="accepted"?"Aceptada":x.status==="rejected"?"Rechazada":"Pendiente"}</span></div>`}).join(""):'<div class="empty-state">Aún no has enviado solicitudes a clubes.</div>'}</section>`;
}
async function openManagedTeam(id){
 const team=await getDoc(doc(db,"teams",id));if(!team.exists())return;
 const t=team.data();if(t.managerUid!==state.user.uid&&t.createdBy!==state.user.uid&&!isAdmin()){toast("No tienes autorización para administrar este equipo.","warning");return}const snap=await getDocs(collection(db,"teams",id,"roster"));
 const host=document.getElementById("manager-team-detail");if(!host)return;
 host.innerHTML=`<section class="panel form-panel"><div class="panel-head"><div><div class="eyebrow green">GESTIÓN DE PLANTILLA</div><h3>${esc(t.name)}</h3></div></div><div class="roster-list">${snap.docs.map(d=>{const p=d.data();return `<div class="history-row"><div><b>${esc(p.displayName||p.email||"Jugador")}</b><small>${esc(p.position||"Posición por definir")} · Dorsal ${esc(p.number||"—")}</small></div><span class="status-pill good">Activo</span></div>`}).join("")||'<div class="empty-state">Esta plantilla todavía no tiene jugadores.</div>'}</div><form id="manager-add-player" class="data-form"><label>Correo de la cuenta<input name="email" type="email" required></label><label>Posición<input name="position" placeholder="Portero, defensa, medio..."></label><label>Dorsal<input name="number" type="number" min="1" max="99"></label><div class="wide"><button class="btn-primary">Agregar jugador →</button></div></form></section>`;
 const form=document.getElementById("manager-add-player");form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),email=String(f.get("email")).trim().toLowerCase();try{const us=await getDocs(query(collection(db,"users"),where("email","==",email),limit(1)));if(us.empty)throw new Error("No encontramos esa cuenta. El jugador debe registrarse primero.");const u=us.docs[0],ud=u.data();await setDoc(doc(db,"teams",id,"roster",u.id),{uid:u.id,email,displayName:ud.displayName||"",position:String(f.get("position")||""),number:Number(f.get("number")||0),status:"active",joinedAt:serverTimestamp()});await setDoc(doc(db,"players",u.id),{uid:u.id,displayName:ud.displayName||"",position:String(f.get("position")||""),teamId:id,teamName:t.name,visibility:"public",updatedAt:serverTimestamp()},{merge:true});toast("Jugador agregado a la plantilla.");openManagedTeam(id)}catch(err){toast(err.message||"No se pudo agregar al jugador.","warning")}};
}
async function createManagerTeam(e){
 e.preventDefault();const f=new FormData(e.currentTarget),leagueId=String(f.get("leagueId")||"");let leagueData={};
 try{if(leagueId){const l=await getDoc(doc(db,"leagues",leagueId));if(l.exists())leagueData={leagueId,leagueName:l.data().name}}
 await addDoc(collection(db,"teams"),{name:String(f.get("name")).trim(),city:String(f.get("city")||""),branch:String(f.get("branch")),category:String(f.get("category")||"Libre"),season:String(f.get("season")||""),...leagueData,status:"active",createdBy:state.user.uid,managerUid:state.user.uid,createdAt:serverTimestamp()});
 toast("Equipo creado. Ya puedes administrar su plantilla.");renderPage()}catch(err){console.error(err);toast("No se pudo crear el equipo. Verifica permisos de Firestore.","warning")}
}
async function requestToJoinTeam(id){
 try{const t=await getDoc(doc(db,"teams",id));if(!t.exists())throw new Error("El equipo ya no está disponible.");const x=t.data();if(x.managerUid===state.user.uid||x.createdBy===state.user.uid)throw new Error("No puedes solicitar unirte a tu propio equipo.");const prior=await getDocs(query(collection(db,"transferRequests"),where("playerUid","==",state.user.uid),where("teamId","==",id),where("status","==","pending"),limit(1)));if(!prior.empty)throw new Error("Ya tienes una solicitud pendiente para este equipo.");await addDoc(collection(db,"transferRequests"),{playerUid:state.user.uid,playerEmail:state.user.email,playerName:state.profile.displayName||state.user.displayName||"Jugador",teamId:id,teamName:x.name,managerUid:x.managerUid||x.createdBy||"",position:state.profile.position||"",status:"pending",createdAt:serverTimestamp()});toast("Solicitud enviada al equipo.");renderPage()}catch(err){toast(err.message||"No se pudo enviar la solicitud.","warning")}
}
async function reviewTransfer(id,accepted){
 try{const r=await getDoc(doc(db,"transferRequests",id));if(!r.exists())throw new Error("Solicitud no encontrada.");const x=r.data();if(x.managerUid!==state.user.uid)throw new Error("No tienes autorización para responder.");await updateDoc(doc(db,"transferRequests",id),{status:accepted?"accepted":"rejected",reviewedBy:state.user.uid,reviewedAt:serverTimestamp()});if(accepted){const team=await getDoc(doc(db,"teams",x.teamId));if(!team.exists())throw new Error("El equipo ya no existe.");await setDoc(doc(db,"teams",x.teamId,"roster",x.playerUid),{uid:x.playerUid,email:x.playerEmail,displayName:x.playerName,position:x.position||"",status:"active",joinedAt:serverTimestamp()});await setDoc(doc(db,"players",x.playerUid),{uid:x.playerUid,displayName:x.playerName,teamId:x.teamId,teamName:team.data().name,visibility:"public",updatedAt:serverTimestamp()},{merge:true})}toast(accepted?"Solicitud aceptada y jugador incorporado.":"Solicitud rechazada.");renderPage()}catch(err){console.error(err);toast(err.message||"No se pudo procesar la solicitud.","warning")}
}

