async function submitManagerTeamRequest(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await addDoc(collection(db,"teamRequests"),{uid:state.user.uid,requesterUid:state.user.uid,teamName:String(f.get("teamName")).trim(),city:String(f.get("city")||""),branch:String(f.get("branch")||"Varonil"),category:String(f.get("category")||"Libre"),season:String(f.get("season")||""),status:"pending",createdAt:serverTimestamp()});toast("Solicitud enviada a la administración.");renderPage()}catch(err){console.error(err);toast("No se pudo enviar la solicitud. Revisa las reglas de Firestore.","warning")}}

function bindPage(){
 const modeSwitch=document.getElementById("mode-switch");if(modeSwitch)modeSwitch.onchange=()=>{state.activeMode=modeSwitch.value;localStorage.setItem("cascarita-active-mode",state.activeMode);state.page=state.activeMode==="manager"?"Modo manager":state.activeMode==="player"?"Modo jugador":"Inicio";shell();renderPage()};

 const verify=document.getElementById("send-verify");if(verify)verify.onclick=async()=>{try{await sendEmailVerification(state.user);toast("Correo de verificación enviado.")}catch(e){toast("No se pudo enviar el correo de verificación.","warning")}};
 const claim=document.getElementById("claim-founder");if(claim)claim.onclick=async()=>{claim.disabled=true;try{await auth.currentUser.reload();if(!auth.currentUser.emailVerified)throw new Error("La cuenta fundadora debe verificar el correo para activar la superadministración.");await auth.currentUser.getIdToken(true);const result=await httpsCallable(functions,"claimFounderSuperadmin")();await auth.currentUser.getIdToken(true);toast(result.data?.message||"Superadministración activada.");location.reload()}catch(e){toast(e.message||"No se pudo activar la superadministración.","warning");claim.disabled=false}};
 const go=document.querySelector("[data-go]");if(go)go.onclick=()=>{state.page=go.dataset.go;renderPage()};document.querySelectorAll("[data-league]").forEach(b=>b.onclick=()=>showLeague(b.dataset.league));
 const pf=document.getElementById("profile-form");if(pf)pf.onsubmit=saveProfile;const photo=document.getElementById("profile-photo");if(photo)photo.onchange=uploadPhoto;
 const lf=document.getElementById("league-form");if(lf)lf.onsubmit=saveLeague;const reset=document.getElementById("league-form-reset");if(reset)reset.onclick=()=>{lf.reset();lf.elements.leagueId.value="";document.getElementById("league-form-title").textContent="Crear competición"};
 const nf=document.getElementById("news-form");if(nf)nf.onsubmit=createNews;const trf=document.getElementById("team-request-form");if(trf)trf.onsubmit=createTeamRequest;
 document.querySelectorAll("[data-approve-role]").forEach(b=>b.onclick=()=>approveRole(b.dataset.approveRole));
 document.querySelectorAll("[data-edit-league]").forEach(b=>b.onclick=()=>editLeague(b.dataset.editLeague));
 document.querySelectorAll("[data-league-status]").forEach(b=>b.onclick=()=>changeLeagueStatus(b.dataset.leagueStatus,b.dataset.status));
 document.querySelectorAll("[data-delete-league]").forEach(b=>b.onclick=()=>deleteLeague(b.dataset.deleteLeague));
 document.querySelectorAll("[data-fixtures]").forEach(b=>b.onclick=()=>generateFixtures(b.dataset.fixtures));
 document.querySelectorAll("[data-team-approve]").forEach(b=>b.onclick=()=>reviewTeamRequest(b.dataset.teamApprove,'approved'));
 document.querySelectorAll("[data-team-reject]").forEach(b=>b.onclick=()=>reviewTeamRequest(b.dataset.teamReject,'rejected'));
 document.querySelectorAll("[data-user-status]").forEach(b=>b.onclick=()=>setUserStatus(b.dataset.userStatus,b.dataset.status));
 document.querySelectorAll("[data-generic-request]").forEach(b=>b.onclick=()=>reviewGenericRequest(b.dataset.genericRequest,b.dataset.kind));
 const search=document.getElementById('user-search');if(search)search.oninput=()=>{const q=search.value.toLowerCase();document.querySelectorAll('#user-directory .history-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))};
 document.querySelectorAll("[data-role-panel]").forEach(b=>b.onclick=()=>{const host=document.getElementById("role-panel-detail");host.innerHTML=`<div class="notice-soft"><b>${esc(b.dataset.rolePanel)}:</b> tu panel está habilitado. Las herramientas específicas se irán incorporando conectadas a los datos y permisos de tu perfil.</div>`});const trf=document.getElementById("team-request-form");if(trf)trf.onsubmit=submitManagerTeamRequest;document.querySelectorAll("[data-manage-team]").forEach(b=>b.onclick=()=>openManagedTeam(b.dataset.manageTeam));document.querySelectorAll("[data-request-team]").forEach(b=>b.onclick=()=>requestToJoinTeam(b.dataset.requestTeam));document.querySelectorAll("[data-transfer-approve]").forEach(b=>b.onclick=()=>reviewTransfer(b.dataset.transferApprove,true));document.querySelectorAll("[data-transfer-reject]").forEach(b=>b.onclick=()=>reviewTransfer(b.dataset.transferReject,false));
}
async function saveProfile(e){e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get("displayName")).trim(),role=String(f.get("roleRequest")||"");try{await updateDoc(doc(db,"users",state.user.uid),{displayName:name,phone:String(f.get("phone")||""),city:String(f.get("city")||""),bio:String(f.get("bio")||""),updatedAt:serverTimestamp()});await updateProfile(state.user,{displayName:name});state.profile={...state.profile,displayName:name,phone:f.get("phone"),city:f.get("city"),bio:f.get("bio")};if(roleList().includes("Jugador")){const playerPosition=String(f.get("playerPosition")||"").trim(),playerVisibility=String(f.get("playerVisibility")||"public");await setDoc(doc(db,"players",state.user.uid),{uid:state.user.uid,displayName:name,position:playerPosition,city:String(f.get("city")||""),visibility:playerVisibility,updatedAt:serverTimestamp()},{merge:true});state.profile.playerPosition=playerPosition;state.profile.playerVisibility=playerVisibility;}if(role){await addDoc(collection(db,"roleRequests"),{uid:state.user.uid,email:state.user.email,name,role,status:"pending",createdAt:serverTimestamp()});toast("Perfil guardado y solicitud de rol enviada.")}else toast("Perfil actualizado.");renderPage()}catch(e){console.error(e);toast("No se pudo guardar. Revisa las reglas de Firestore.","warning")}}
async function uploadPhoto(e){const file=e.target.files?.[0];if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){toast("Elige JPG, PNG o WEBP de máximo 5 MB.","warning");return}try{const path=`profilePhotos/${state.user.uid}/avatar-${Date.now()}`;const r=storageRef(storage,path);await uploadBytes(r,file,{contentType:file.type});const url=await getDownloadURL(r);await updateDoc(doc(db,"users",state.user.uid),{photoURL:url,photoPath:path,updatedAt:serverTimestamp()});state.profile.photoURL=url;toast("Fotografía actualizada.");renderPage()}catch(err){console.error(err);toast("No se pudo subir la foto. Revisa Storage Rules.","warning")}}
async function saveLeague(e){e.preventDefault();const f=new FormData(e.currentTarget),payload={leagueId:String(f.get('leagueId')||''),name:String(f.get('name')).trim(),season:String(f.get('season')).trim(),city:String(f.get('city')).trim(),branch:String(f.get('branch')),category:String(f.get('category')||'').trim(),modality:String(f.get('modality')),format:String(f.get('format')),teamLimit:Number(f.get('teamLimit')),legs:Number(f.get('legs')),status:String(f.get('status')),pointsWin:Number(f.get('pointsWin')),pointsDraw:Number(f.get('pointsDraw')),pointsLoss:Number(f.get('pointsLoss')),tieBreakers:String(f.get('tieBreakers')||'Puntos, diferencia de goles, goles a favor').trim()};try{await httpsCallable(functions,'adminSaveLeague')(payload);toast('Competición guardada.');renderPage()}catch(err){console.error(err);toast(err.message||'No se pudo guardar la competición.','warning')}}
async function editLeague(id){try{const snap=await getDoc(doc(db,'leagues',id));if(!snap.exists())throw new Error('Competición no encontrada');const x=snap.data(),f=document.getElementById('league-form');for(const k of ['name','season','city','branch','category','modality','format','teamLimit','legs','status','pointsWin','pointsDraw','pointsLoss','tieBreakers'])if(f.elements[k])f.elements[k].value=x[k]??({teamLimit:16,legs:2,pointsWin:3,pointsDraw:1,pointsLoss:0}[k]??'');f.elements.leagueId.value=id;document.getElementById('league-form-title').textContent='Editar competición';f.scrollIntoView({behavior:'smooth',block:'center'})}catch(e){toast(e.message,'warning')}}
async function changeLeagueStatus(id,status){try{await httpsCallable(functions,'adminSaveLeague')({leagueId:id,status});toast('Estado de competición actualizado.');renderPage()}catch(e){toast(e.message||'No se pudo actualizar.','warning')}}
async function deleteLeague(id){if(!confirm('¿Eliminar esta competición? Solo se permitirá si no tiene equipos ni partidos.'))return;try{await httpsCallable(functions,'adminDeleteLeague')({leagueId:id});toast('Competición eliminada.');renderPage()}catch(e){toast(e.message||'No se pudo eliminar.','warning')}}
async function generateFixtures(id){if(!confirm('Se generará el calendario automáticamente con los equipos aprobados. No se puede repetir si ya existen encuentros. ¿Continuar?'))return;try{const r=await httpsCallable(functions,'generateLeagueFixtures')({leagueId:id});toast(r.data?.message||'Calendario generado.');renderPage()}catch(e){console.error(e);toast(e.message||'No se pudo generar el calendario.','warning')}}
async function reviewTeamRequest(id,status){try{const r=await httpsCallable(functions,'reviewTeamRequest')({requestId:id,status});toast(r.data?.message||'Solicitud procesada.');renderPage()}catch(e){console.error(e);toast(e.message||'No se pudo procesar la solicitud.','warning')}}
async function setUserStatus(uid,status){if(!confirm(status==='suspended'?'¿Suspender el acceso de esta cuenta?':status==='deactivated'?'¿Dar de baja esta cuenta?':'¿Reactivar esta cuenta?'))return;try{await httpsCallable(functions,'setUserAccessStatus')({uid,status});toast('Acceso actualizado.');renderPage()}catch(e){toast(e.message||'No se pudo cambiar el acceso.','warning')}}
async function reviewGenericRequest(id,kind){const status=confirm('¿Aprobar esta solicitud?')?'approved':'rejected';try{await httpsCallable(functions,'reviewOrganizationRequest')({requestId:id,kind,status});toast('Solicitud revisada.');renderPage()}catch(e){toast(e.message||'No se pudo revisar.','warning')}}
async function createTeamRequest(e){e.preventDefault();const f=new FormData(e.currentTarget),leagueId=String(f.get("leagueId")),league=await getDoc(doc(db,"leagues",leagueId));if(!league.exists()){toast("La competición ya no está disponible.","warning");return}try{await addDoc(collection(db,"teamRequests"),{uid:state.user.uid,email:state.user.email,name:state.profile.displayName||state.user.displayName||"",teamName:String(f.get("teamName")).trim(),clubName:String(f.get("clubName")).trim(),city:String(f.get("city")).trim(),branch:String(f.get("branch")),category:String(f.get("category")||"").trim(),leagueId,leagueName:league.data().name,status:"pending",createdAt:serverTimestamp()});toast("Solicitud enviada a la administración.");renderPage()}catch(err){console.error(err);toast(err.message||"No se pudo enviar la solicitud.","warning")}}
async function createNews(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await addDoc(collection(db,"news"),{title:String(f.get("title")).trim(),body:String(f.get("body")).trim(),published:true,authorUid:state.user.uid,createdAt:serverTimestamp()});toast("Noticia publicada.");renderPage()}catch(err){console.error(err);toast("No se pudo publicar la noticia.","warning")}}
async function approveRole(id){try{await httpsCallable(functions,"reviewRoleRequest")({requestId:id,status:"approved"});toast("Rol aprobado.");renderPage()}catch(e){console.error(e);toast(e.message||"No se pudo aprobar el rol.","warning")}}

async function showLeague(id){const l=state.leagues.find(x=>x.id===id);if(!l)return;const [teams,matches]=await Promise.all([getDocs(query(collection(db,"teams"),where("leagueId","==",id))),getDocs(query(collection(db,"matches"),where("leagueId","==",id)))]);const host=document.getElementById("league-detail");if(!host)return;const standings={};teams.forEach(d=>standings[d.id]={name:d.data().name,pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0});matches.forEach(d=>{const m=d.data();if(m.status!=="final"||m.homeGoals==null||m.awayGoals==null||!standings[m.homeTeamId]||!standings[m.awayTeamId])return;const h=standings[m.homeTeamId],a=standings[m.awayTeamId];h.pj++;a.pj++;h.gf+=m.homeGoals;h.gc+=m.awayGoals;a.gf+=m.awayGoals;a.gc+=m.homeGoals;if(m.homeGoals>m.awayGoals){h.pg++;h.pts+=3;a.pp++}else if(m.homeGoals<m.awayGoals){a.pg++;a.pts+=3;h.pp++}else{h.pe++;a.pe++;h.pts++;a.pts++}});const table=Object.values(standings).sort((a,b)=>b.pts-a.pts||(b.gf-b.gc)-(a.gf-a.gc)||b.gf-a.gf);host.innerHTML=`<section class="panel"><div class="eyebrow green">${esc(l.season||"")}</div><h2>${esc(l.name)}</h2><p>${esc(l.city||"")} · ${esc(l.branch||"")}</p><h3>Tabla de posiciones</h3>${table.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>Equipo</th><th>PJ</th><th>PG</th><th>PE</th><th>PP</th><th>GF</th><th>GC</th><th>PTS</th></tr></thead><tbody>${table.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}</td><td>${t.pj}</td><td>${t.pg}</td><td>${t.pe}</td><td>${t.pp}</td><td>${t.gf}</td><td>${t.gc}</td><td><b>${t.pts}</b></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">La tabla se calculará conforme se registren equipos y resultados validados.</div>'}<h3>Equipos participantes</h3>${teams.empty?'<div class="empty-state">Todavía no hay equipos inscritos.</div>':teams.docs.map(d=>`<div class="history-row"><b>${esc(d.data().name)}</b><small>${esc(d.data().branch||"")}</small></div>`).join("")}<h3>Encuentros</h3>${matches.empty?'<div class="empty-state">Todavía no hay encuentros programados.</div>':matches.docs.map(d=>{const m=d.data();return `<div class="history-row"><div><b>${esc(m.homeTeam)} vs ${esc(m.awayTeam)}</b><small>${m.kickoff?.toDate?m.kickoff.toDate().toLocaleString("es-MX"):"Fecha por confirmar"}</small></div><strong>${m.status==="final"?`${m.homeGoals} - ${m.awayGoals}`:"Programado"}</strong></div>`}).join("")}</section>`}

onAuthStateChanged(auth,async user=>{state.user=user;if(!user){state.admin=false;state.profile={};authView();return}try{const token=await getIdTokenResult(user,true);state.claims=token.claims;state.admin=token.claims.superadmin===true;const ref=doc(db,"users",user.uid),snap=await getDoc(ref);if(!snap.exists()){await setDoc(ref,{displayName:user.displayName||"",email:user.email||"",roles:[state.pendingInitialRole||"Aficionado"],status:"active",createdAt:serverTimestamp(),updatedAt:serverTimestamp()});state.profile={displayName:user.displayName||"",email:user.email,roles:[state.pendingInitialRole||"Aficionado"]}}else state.profile=snap.data();if(!Array.isArray(state.profile.roles))state.profile.roles=["Aficionado"];state.page="Inicio";shell()}catch(e){console.error(e);toast("No se pudo cargar tu perfil o tus permisos.","warning");shell()}});
